type podeliRefundPayment struct {
	api        podeli.PodeliPayments
	systemData *domain.SystemData
	log        logger.Logger
}

func NewPodeliRefundPayment(api podeli.PodeliPayments, systemData *domain.SystemData, log logger.Logger) RefundPaymentInterface {
	return &podeliRefundPayment{
		api:        api,
		systemData: systemData,
		log:        log,
	}
}

func (p *podeliRefundPayment) GetName() domain.PaymentSystem {
	return domain.PaymentSystemPodeli
}

func (p *podeliRefundPayment) Refund(ctx context.Context, order *models.Order, amount int64) error {
	if order.Podeli == nil || order.Podeli.ID == "" {
		return fmt.Errorf("Refund error: order does not have Podeli Order ID")
	}

	req := &podeli.RefundPaymentRequest{}
	req.Order.Refund.ID = order.Podeli.ID
	req.Order.Refund.Initiator = podeli.ShopInitiator
	for _, item := range order.ItemsWithProducts {
		req.Order.Refund.Items = append(req.Order.Refund.Items, podeli.RefundedItem{
			ID:               strconv.Itoa(int(item.Item.ID)),
			RefundedQuantity: int(item.Quantity),
		})
	}

	// amount == полная сумма заказа означает возврат "включая доставку" (см. RefundPayment в orders.go),
	// item доставки регистрировался в Podeli отдельной позицией с ID "delivery" при создании заказа
	if amount >= order.Price.PartForPaymentInCurrency {
		req.Order.Refund.Items = append(req.Order.Refund.Items, podeli.RefundedItem{
			ID:               "delivery",
			RefundedQuantity: 1,
		})
	}

	err := p.api.RefundPayment(ctx, req)
	if err != nil {
		return fmt.Errorf("Refund/PodeliPayments.RefundPayment: %w", err)
	}

	return nil
}
